double minor = 0;
for (int i = 0; i < 3; i++) {
    if (i == row) continue;
    for (int j = 0; j < 3; j++) {
        if (j == col) continue;
        int ii = (i < row) ? i : i - 1;
        int jj = (j < col) ? j : j - 1;
        if (ii == 0 && jj == 0) minor += m[i][j] * m[1][1];
        else if (ii == 0 && jj == 1) minor += m[i][j] * (-m[1][0]);
        else if (ii == 1 && jj == 0) minor += m[i][j] * (-m[0][1]);
        else if (ii == 1 && jj == 1) minor += m[i][j] * m[0][0];
    }
}
return ((row + col) % 2 == 0) ? minor : -minor;

